import { h } from "@stencil/core";
export function nearestLowerMultiple(number, multipleOf = window.matchMedia('(min-width: 768px)').matches ? 3 : 2) {
    return number < multipleOf ? number : number - (number % multipleOf);
}
export function closeModals(cb = null) {
    for (const element of document.querySelectorAll('salla-modal')) {
        element.close();
    }
    cb && requestAnimationFrame(cb);
}
export function normalizeLoyaltyData(data) {
    const groups = (data.prizes || []).map((group) => {
        return {
            ...group,
            items: (group.items || []).map((item) => ({ ...item, group_title: group.title, group_type: group.type })),
        };
    });
    const all = {
        type: 'all',
        title: salla.lang.get('pages.loyalty_program.all'),
        items: groups.reduce((acc, group) => acc.concat(group.items), []),
    };
    groups.unshift(all);
    return {
        ...data,
        prizes: groups,
        prizes_count: all.items.length,
        points: data.points ?? [],
    };
}
export function brand_path(brand) {
    return [brand.name.replace(/\s/g, '-'), `brand-${brand.id}`].join('/');
}
export function isUnitOrder(point) {
    for (const condition of point.conditions) {
        if (condition.key.endsWith('_FOR_UNIT') || condition.key.endsWith('_FOR_UNIT_BY_CATEGORIES')) {
            return true;
        }
    }
}
export function isRangePoints(point) {
    for (const condition of point.conditions) {
        if (condition.key.endsWith('_BY_CATEGORIES') && point.conditions.length > 1) {
            return true;
        }
    }
}
export function getPoints(point) {
    if (isRangePoints(point)) {
        return point.conditions.sort((a, b) => a.points - b.points)[0].points;
    }
    return point.points;
}
export function formattedPointsJsx(value, isUnit = false, isRange = false) {
    if (typeof value === 'number') {
        if (isUnit) {
            return h("span", null, isRange ? salla.lang.get('pages.loyalty_program.start_from') : '', " 1 ", salla.config.currency().symbol, " = ", value, " ", salla.lang.get('pages.loyalty_program.point'));
        }
        return h("span", null, isRange ? salla.lang.get('pages.loyalty_program.start_from') : '', " ", value, " ", salla.lang.get('pages.loyalty_program.point'));
    }
    if (isUnitOrder(value)) {
        return h("span", null, isRangePoints(value) ? salla.lang.get('pages.loyalty_program.start_from') : '', " 1 ", salla.config.currency().symbol, " = ", getPoints(value), " ", salla.lang.get('pages.loyalty_program.point'));
    }
    return h("span", null, isRangePoints(value) ? salla.lang.get('pages.loyalty_program.start_from') : '', " ", getPoints(value), " ", salla.lang.get('pages.loyalty_program.point'));
}
